import { useEffect, useState, type ReactNode } from 'react'

import { useNavigate, useParams } from 'react-router-dom'

import { Box, CircularProgress, Alert } from '@mui/material'

import {
  findOverlappingFmPlans,
  getTrainingPlan,
  isUniqueViolation,
  updateTrainingPlan,
} from '@/api/trainingPlans'
import { routes } from '@/routes'
import type { TrainingPlan } from '@/types/database'

import {
  PlanForm,
  PlanPathOverlapMessage,
  planToFormData,
  formDataToPlanUpdate,
  type PlanFormData,
} from '../components'

export function PlansEditPage() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const [plan, setPlan] = useState<TrainingPlan | null>(null)
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<ReactNode | null>(null)

  useEffect(() => {
    if (id) {
      loadPlan(Number(id))
    }
  }, [id])

  async function loadPlan(planId: number) {
    try {
      setLoading(true)
      const data = await getTrainingPlan(planId)
      setPlan(data)
    } catch (err) {
      setError('훈련 계획을 불러오는데 실패했습니다.')
      // eslint-disable-next-line no-console
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  async function handleSubmit(data: PlanFormData) {
    if (!plan) return

    if (!data.name.trim()) {
      setError('계획 이름을 입력해주세요.')
      return
    }
    if (!data.unitName.trim()) {
      setError('훈련 단위를 입력해주세요.')
      return
    }
    if (data.scheduleType === 'weekly' && data.scheduleDays.length === 0) {
      setError('훈련 요일을 선택해주세요.')
      return
    }

    try {
      setSubmitting(true)
      setError(null)

      // unit_name 이 바뀌어 다른 플랜의 폴더와 겹치는 경우. 자기 자신은 제외.
      if (data.unitName !== plan.unit_name) {
        const [overlapping] = await findOverlappingFmPlans(plan.user_id, data.unitName, plan.id)
        if (overlapping) {
          setError(<PlanPathOverlapMessage plan={overlapping} />)
          return
        }
      }

      await updateTrainingPlan(plan.id, formDataToPlanUpdate(data))
      navigate(routes.plans.detail.$path({ id: plan.id }, {}))
    } catch (err) {
      setError(
        isUniqueViolation(err)
          ? '같은 폴더를 가리키는 계획이 이미 있습니다. 기존 계획을 재사용해 주세요.'
          : '계획 수정에 실패했습니다.'
      )
      // eslint-disable-next-line no-console
      console.error(err)
    } finally {
      setSubmitting(false)
    }
  }

  function handleCancel() {
    if (plan) {
      navigate(routes.plans.detail.$path({ id: plan.id }, {}))
    } else {
      navigate(routes.plans.$())
    }
  }

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress />
      </Box>
    )
  }

  if (!plan) {
    return <Alert severity="warning">훈련 계획을 찾을 수 없습니다.</Alert>
  }

  return (
    <PlanForm
      initialData={planToFormData(plan)}
      onSubmit={handleSubmit}
      onCancel={handleCancel}
      loading={submitting}
      error={error}
      title="훈련 계획 수정"
      submitLabel="저장"
      loadingLabel="저장 중..."
    />
  )
}
